import re


class Emil_Msg_Handle(object):
    def __init__(self):
        pass

    def parse_key_value(self, line):
        'key value'
        pass

    def msg_2_dict(self, data):
        'dict'
        pass

    def parse_single_msg(self, msg):
        'null'
        useful_list = []
        lines = msg.splitlines()
        for line in lines:
            if '=' in line:
                useful_list.append(line.replace('=', ' = '))
        return useful_list

    def parse_file(self, file_path):
        'null'
        with open(file_path, 'r') as obj:
            lines = obj.read()
        msg_dict = {}

        line_num = []
        lines = lines.split('\n\n')
        start = 0
        for line in lines:
            ret = re.search(r'id=(\d+)', line)
            if ret:
                id = int(ret.groups()[0])
                msg = self.parse_single_msg(line)
                msg_dict[id] = msg
        self.search_list = sorted(msg_dict)

        with open('%s_decode' % file_path, 'w') as obj:
            for i in sorted(msg_dict):
                obj.writelines('\r\n'.join(msg_dict[i]) + '\r\n\r\n')
        return msg_dict
